async function api(path,opt={}){const headers={...authHeaders(),...(opt.headers||{})};if(opt.body&&!headers['Content-Type'])headers['Content-Type']='application/json';const r=await fetch(path,{...opt,headers,credentials:'same-origin'});let data=null;const ct=r.headers.get('content-type')||'';if(ct.includes('json'))data=await r.json().catch(()=>null);else data=await r.text();if(!r.ok){const e=new Error(data?.error?.message||data?.message||`HTTP ${r.status}`);e.status=r.status;throw e}return data}
