async function refreshAll(loud){try{const jobs=[api('/gateway/v1/usage/me').then(x=>S.myUsage=x)];if(isAdmin()){jobs.push(api('/gateway/ui-api/overview').then(x=>S.overview=x),api('/gateway/ui-api/recent?limit=1000').then(x=>S.recent=x.events||[]),api('/gateway/ui-api/policies').then(x=>S.policies=x),api('/gateway/ui-api/jobs').then(x=>S.jobs=x.jobs||[]),api('/gateway/ui-api/batches').then(x=>S.batches=x),api('/gateway/ui-api/operations').then(x=>S.operations=x.operations||[]));if(['models','workers','overview'].includes(S.page)||!S.models.length)jobs.push(api('/gateway/ui-api/models').then(x=>S.models=x.inventories||[]));if(S.page==='models'||S.aliases===null)jobs.push(api('/gateway/ui-api/model-aliases').then(x=>S.aliases=x));if(S.page==='routing'||S.placement===null)jobs.push(api('/gateway/ui-api/placement').then(x=>S.placement=x));if(['security','config'].includes(S.page)&&!S.config)jobs.push(api('/gateway/ui-api/config').then(x=>S.config=x));if(S.page==='security'||S.apiKeys===null)jobs.push(api('/gateway/ui-api/api-keys').then(x=>S.apiKeys=x.keys||[]));if(S.page==='autotune'||S.autotune===null)jobs.push(api('/gateway/ui-api/autotune').then(x=>S.autotune=x));if(S.page==='warm'||S.warm===null)jobs.push(api('/gateway/ui-api/warm-models').then(x=>S.warm=x));if(S.page==='alerts'||S.alerts===null)jobs.push(api('/gateway/ui-api/alerts').then(x=>S.alerts=x));if(S.page==='storage'||S.storage===null)jobs.push(api('/gateway/ui-api/storage').then(x=>S.storage=x));if(S.page==='usage')jobs.push(loadRollups())}await Promise.all(jobs);setConnection(true);render();if(loud)toast('Aktualisiert')}catch(e){setConnection(false,e.message);if(e.status===401)return showLogin('Sitzung abgelaufen oder Credential ungültig.');if(loud)toast(e.message,true)}}
function setConnection(ok,msg=''){$('#connection-state').className='status-line '+(ok?'ok':'bad');$('#connection-state span:last-child').textContent=ok?'Gateway verbunden':(msg||'Verbindung gestört')}
