function renderSecurity(){const c=S.config,auth=c.auth||{},oidc=auth.oidc||{},keys=S.apiKeys||[];const keyRows=keys.length?keys.map(k=>`<div class="api-key-row"><div class="grow"><div class="api-key-title"><strong>${esc(k.name)}</strong><span class="status-chip ${k.source==='persistent'?'ok':k.source==='runtime'?'warn':''}">${esc(k.source||'config')}</span></div><small>${esc(k.tenant)} · ${esc(k.application||k.subject||'–')}</small><div class="api-key-meta"><span class="mono">${esc(k.key_hint||'Secret redacted')}</span>${k.service_class?`<span>QoS: ${esc(k.service_class)}</span>`:''}${(k.scopes||[]).length?`<span>${esc(k.scopes.join(', '))}</span>`:'<span>keine Scopes</span>'}${(k.allowed_models||[]).length?`<span>Allow: ${esc(k.allowed_models.join(', '))}</span>`:''}${(k.denied_models||[]).length?`<span>Deny: ${esc(k.denied_models.join(', '))}</span>`:''}${k.created_at?`<span>${esc(when(k.created_at))}</span>`:''}</div></div>${k.deletable?`<button class="button small danger-button" type="button" data-api-key-delete="${esc(k.id)}" data-api-key-name="${esc(k.name)}">Löschen</button>`:'<span class="muted api-key-locked">aus Konfiguration</span>'}</div>`).join(''):'<div class="empty">Keine API-Keys</div>';const cards=[['OIDC',`<div class="kv"><div>Status</div><div>${oidc.enabled?'aktiv':'inaktiv'}</div><div>Issuer</div><div class="mono">${esc(oidc.issuer||'–')}</div><div>Audience</div><div class="mono">${esc(oidc.audience||'–')}</div><div>Admin Groups</div><div>${esc((oidc.admin_groups||[]).join(', ')||'–')}</div></div>`],['API Keys',`<div class="security-card-head"><div><p>UI-Keys werden persistent gespeichert; im State liegt ausschließlich ihr SHA-256-Hash.</p></div><button id="new-api-key" class="button primary small" type="button">API-Key erstellen</button></div><div class="api-key-list">${keyRows}</div>`],['Persistenz',`<div class="kv"><div>Data directory</div><div class="mono">${esc(c.storage?.data_dir||'–')}</div><div>Config</div><div class="mono">${esc(c.storage?.config_file||'–')}</div><div>API keys</div><div class="mono">${esc(c.storage?.api_keys_file||'–')}</div><div>Policies</div><div class="mono">${esc(c.storage?.policies_file||'–')}</div><div>Metrics</div><div class="mono">${esc(c.storage?.metrics_file||'–')}</div><div>Quota</div><div class="mono">${esc(c.storage?.quota_file||'–')}</div><div>Worker performance</div><div class="mono">${esc(c.storage?.worker_performance_file||'–')}</div><div>Model placement</div><div class="mono">${esc(c.storage?.model_placement_file||'–')}</div><div>Worker state</div><div class="mono">${esc(c.storage?.worker_state_file||'–')}</div><div>Usage</div><div class="mono">${esc(c.usage?.journal_dir||'–')}</div></div>`],['IP Bypass',auth.ip_bypass?.length?auth.ip_bypass.map(x=>`<div class="health-item"><div><strong>${esc((x.cidrs||[]).join(', '))}</strong><small>${esc(x.tenant)} · ${esc(x.subject||'')}</small></div></div>`).join(''):'<div class="empty">Kein IP-Bypass</div>'],['Trusted Proxies',`<div class="model-tags">${(auth.trusted_proxies||[]).map(x=>`<span class="model-tag mono">${esc(x)}</span>`).join('')||'<span class="muted">Keine</span>'}</div>`]];$('#security-grid').innerHTML=cards.map(([t,b])=>`<article class="panel security-card"><h3>${t}</h3>${b}</article>`).join('');$('#new-api-key')?.addEventListener('click',openAPIKeyDialog)}

function openAPIKeyDialog(){const f=$('#api-key-form');f.reset();$('#api-key-tenant').value=S.session?.tenant||'';const sel=$('#api-key-service-class'),cls=Object.keys(S.overview?.service_classes?.classes||{}).sort();if(sel)sel.innerHTML='<option value="">Gateway-Default</option>'+cls.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('');$('#api-key-dialog').showModal()}
$('#api-key-form')?.addEventListener('submit',async e=>{e.preventDefault();const splitRules=v=>v.split(/[\n,]+/).map(x=>x.trim()).filter(Boolean);const scopes=$('#api-key-scopes').value.split(',').map(x=>x.trim()).filter(Boolean);const body={name:$('#api-key-name').value.trim(),tenant:$('#api-key-tenant').value.trim(),subject:$('#api-key-subject').value.trim(),application:$('#api-key-application').value.trim(),scopes,allowed_models:splitRules($('#api-key-allowed-models').value),denied_models:splitRules($('#api-key-denied-models').value),service_class:$('#api-key-service-class')?.value||''};if(!body.name||!body.tenant)return toast('Name und Tenant sind erforderlich.',true);try{const out=await api('/gateway/ui-api/api-keys',{method:'POST',body:JSON.stringify(body)});$('#api-key-dialog').close();$('#created-key-name').textContent=out.key?.name||body.name;$('#created-key-secret').value=out.secret||'';$('#created-key-dialog').showModal();S.apiKeys=(await api('/gateway/ui-api/api-keys')).keys||[];renderSecurity();toast('API-Key erstellt')}catch(err){toast(err.message,true)}});
