$('#copy-config').onclick=async()=>{if(await copyText($('#config-json').value))toast('Konfiguration kopiert');else toast('Kopieren nicht möglich.',true)};
function setConfigEditing(on){const ed=$('#config-json');if(!ed)return;ed.readOnly=!on;S.configDirty=on;$('#config-actions')?.classList.toggle('hidden',!on);$('#edit-config').textContent=on?'Bearbeitung aktiv':'Bearbeiten';if(on){ed.focus();$('#config-status').textContent='JSON wird vor dem Speichern vollständig validiert. Aktivierung aller Änderungen erfolgt nach einem Gateway-Neustart.'}else{$('#config-status').textContent='Effektive Konfiguration. Änderungen an der Storage-Sektion sind nur in der Bootstrap-Datei möglich.'}}
