function table(headers,rows){if(!rows.length)return '<div class="empty">Keine Daten</div>';return `<table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c??''}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.modelAction)modelAction(b.dataset.modelAction,b.dataset.worker,b.dataset.model);else if(b.dataset.policyEdit!==undefined)openPolicy(b.dataset.policyEdit);else if(b.dataset.policyDelete!==undefined)deletePolicy(b.dataset.policyDelete);else if(b.dataset.jobCancel)cancelJob(b.dataset.jobCancel);else if(b.dataset.batchAction)batchAction(b.dataset.batchId,b.dataset.batchAction);else if(b.dataset.batchOutput)downloadBatchOutput(b.dataset.batchOutput);else if(b.dataset.operationCancel)cancelOperation(b.dataset.operationCancel)});


// ---- Local in-memory infrastructure map -------------------------------------
function stopClusterStream(){if(S.clusterAbort){S.clusterAbort.abort();S.clusterAbort=null}S.cluster.connected=false;updateClusterConnection()}
function startClusterStream(){if(!isAdmin()||S.clusterAbort)return;const ctl=new AbortController();S.clusterAbort=ctl;void clusterStreamLoop(ctl.signal)}
async function clusterStreamLoop(signal){let retry=700;while(!signal.aborted){try{await clusterStreamOnce(signal);retry=700}catch(e){if(signal.aborted)return;S.cluster.connected=false;updateClusterConnection(e.message);if(e.status===401){showLogin('Sitzung abgelaufen oder Credential ungültig.');return}try{handleClusterSnapshot(await api('/gateway/ui-api/infrastructure'))}catch{}await liveSleep(retry,signal);retry=Math.min(5000,retry*1.7)}}}
async function clusterStreamOnce(signal){const headers=authHeaders();headers.Accept='text/event-stream';const r=await fetch('/gateway/ui-api/infrastructure/stream',{headers,credentials:'same-origin',signal});if(!r.ok){const e=new Error(`Infrastructure-Stream HTTP ${r.status}`);e.status=r.status;throw e}if(!r.body)throw new Error('Infrastructure-Stream nicht verfügbar');S.cluster.connected=true;updateClusterConnection();const reader=r.body.getReader(),decoder=new TextDecoder();let buf='';while(!signal.aborted){const {value,done}=await reader.read();if(done)throw new Error('Infrastructure-Stream beendet');buf+=decoder.decode(value,{stream:true}).replace(/\r\n/g,'\n');let i;while((i=buf.indexOf('\n\n'))>=0){const raw=buf.slice(0,i);buf=buf.slice(i+2);let event='message';const data=[];for(const line of raw.split('\n')){if(line.startsWith('event:'))event=line.slice(6).trim();else if(line.startsWith('data:'))data.push(line.slice(5).trimStart())}if(event==='snapshot'&&data.length){try{handleClusterSnapshot(JSON.parse(data.join('\n')))}catch{}}}}}
function handleClusterSnapshot(x){S.cluster={...S.cluster,...x,gateways:Array.isArray(x?.gateways)?x.gateways:[],workers:Array.isArray(x?.workers)?x.workers:[],requests:Array.isArray(x?.requests)?x.requests:[],counts:x?.counts||{},connected:true};updateClusterConnection();renderClusterPanel()}
function updateClusterConnection(msg=''){const el=$('#cluster-stream-state');if(!el)return;el.className='status-chip '+(S.cluster.connected?'ok':'warn');el.textContent=S.cluster.connected?'In-Memory live':(msg?'Reconnect':'verbinde …')}
function clusterFilteredRequests(includeTerminal=true){const q=($('#cluster-search')?.value||'').trim().toLowerCase();return (S.cluster.requests||[]).filter(r=>(includeTerminal||liveActive(r))&&(!q||`${r.gateway_name||''} ${r.tenant||''} ${r.actor||''} ${r.worker||''} ${r.model||''}`.toLowerCase().includes(q)))}
function pct(v,total){return total>0?Math.max(0,Math.min(100,100*Number(v||0)/Number(total))):0}
function renderClusterPanel(){if(!isAdmin())return;const c=S.cluster.counts||{};$('#cluster-gateways')&&($('#cluster-gateways').textContent=num(c.gateways??S.cluster.gateways.length));$('#cluster-workers')&&($('#cluster-workers').textContent=num(c.workers??S.cluster.workers.length));$('#cluster-active')&&($('#cluster-active').textContent=num(c.active??clusterFilteredRequests(false).length));$('#cluster-queue')&&($('#cluster-queue').textContent=num(S.cluster.queue||0));$('#cluster-models')&&($('#cluster-models').textContent=num(c.models||0));$('#cluster-map-empty')?.classList.toggle('hidden',(S.cluster.gateways?.length||0)>0);renderClusterGateways();renderClusterWorkers();updateClusterConnection()}
function renderClusterGateways(){const el=$('#cluster-gateway-list');if(!el)return;const gs=S.cluster.gateways||[];el.innerHTML=gs.length?gs.map(g=>{const age=Math.max(0,(Date.now()-new Date(g.last_seen).getTime())/1000);return `<div class="cluster-node"><div class="cluster-node-head"><div><strong>${esc(g.node_name)}</strong><small>${esc(g.hostname||g.node_id)}</small></div><span class="status-chip ${age<8?'ok':'warn'}">${age<3?'live':age.toFixed(0)+'s'}</span></div><div class="cluster-mini-grid"><span>Queue <b>${num(g.queued)}</b></span><span>Running <b>${num(g.running)}</b></span><span>Requests <b>${num(g.live_active)}</b></span><span>Worker <b>${num(g.workers)}</b></span></div></div>`}).join(''):'<div class="empty">Keine Gateway-Nodes</div>'}
function renderClusterWorkers(){const el=$('#cluster-worker-list');if(!el)return;const ws=S.cluster.workers||[];el.innerHTML=ws.length?ws.map(w=>{const memUsed=Number(w.memory_used_bytes||w.resident_bytes||0),memTotal=Number(w.memory_total_bytes||w.memory_capacity_bytes||0),vrUsed=Number(w.vram_used_bytes||w.vram_bytes||0),vrTotal=Number(w.vram_total_bytes||w.vram_capacity_bytes||0),vp=pct(vrUsed,vrTotal),mp=pct(memUsed,memTotal),models=(w.loaded_models||[]).slice(0,5),memLabel=w.memory_used_bytes?'System RAM':'Model resident',vrLabel=w.vram_used_bytes?'VRAM used':'VRAM footprint',gpu=Number(w.gpu_utilization_percent||0);return `<div class="cluster-node"><div class="cluster-node-head"><div><strong>${esc(w.name)}</strong><small>${esc((w.gateways||[]).join(', ')||w.url)}${w.telemetry_source?` · ${esc(w.telemetry_source)}`:''}</small></div><span class="status-chip ${w.healthy?'ok':'bad'}">${w.active}/${w.max_concurrent}</span></div><div class="resource-line"><span>${memLabel}</span><b>${bytes(memUsed)}${memTotal?' / '+bytes(memTotal):''}</b></div><div class="resource-bar"><i style="width:${memTotal?mp:Math.min(100,10+(w.loaded_models?.length||0)*15)}%"></i></div><div class="resource-line"><span>${vrLabel}</span><b>${bytes(vrUsed)}${vrTotal?' / '+bytes(vrTotal):''}</b></div><div class="resource-bar vram"><i style="width:${vrTotal?vp:Math.min(100,10+(w.loaded_models?.length||0)*15)}%"></i></div>${gpu?`<div class="resource-line"><span>GPU utilization</span><b>${num(gpu,1)}%</b></div><div class="resource-bar gpu"><i style="width:${Math.min(100,gpu)}%"></i></div>`:''}<div class="live-worker-models">${models.map(m=>`<span>${esc(m.name||m.model)} · ${bytes(m.size_vram)}</span>`).join('')||'<span>idle</span>'}</div>${w.telemetry_error?`<small class="muted">Telemetry: ${esc(w.telemetry_error)}</small>`:''}</div>`}).join(''):'<div class="empty">Keine Worker</div>'}
function clusterLayout(reqs,W,H){const gs=(S.cluster.gateways||[]).slice(0,8),ws=(S.cluster.workers||[]).slice(0,12),margin=65,gatewayPos=new Map(),queuePos=new Map(),workerPos=new Map(),modelPos=new Map(),tenantPos=new Map();const tenants=[...new Set(reqs.map(r=>r.tenant).filter(Boolean))].slice(0,9);tenants.forEach((n,i)=>tenantPos.set(n,{x:Math.max(55,W*.055),y:margin+(H-2*margin)*(tenants.length===1?.5:i/Math.max(1,tenants.length-1))}));gs.forEach((g,i)=>{const y=margin+(H-2*margin)*(gs.length===1?.5:i/Math.max(1,gs.length-1));gatewayPos.set(g.node_name,{x:W*.27,y});queuePos.set(g.node_name,{x:W*.44,y})});ws.forEach((w,i)=>{const y=margin+(H-2*margin)*(ws.length===1?.5:i/Math.max(1,ws.length-1));const key=w.name+'\0'+w.url,lm=w.loaded_models||[];workerPos.set(key,{x:W*.72,y,w});for(const [j,m] of lm.slice(0,4).entries()){const off=(j-(Math.min(4,lm.length)-1)/2)*24;modelPos.set(key+'\0'+(m.name||m.model),{x:W*.94,y:Math.max(36,Math.min(H-36,y+off)),m})}});return{tenantPos,gatewayPos,queuePos,workerPos,modelPos,gateways:gs,workers:ws}}
function clusterWorkerPoint(l,r){for(const [k,p] of l.workerPos){if(p.w.name===r.worker)return {key:k,p}}return null}
function clusterRoute(l,r,H){const tp=l.tenantPos.get(r.tenant)||{x:55,y:40+(liveHash(r.tenant)%(Math.max(80,H-80)))},gp=l.gatewayPos.get(r.gateway_name)||{x:220,y:H*.5},qp=l.queuePos.get(r.gateway_name)||{x:360,y:gp.y},wp=clusterWorkerPoint(l,r),w=wp?.p||{x:qp.x+220,y:H*.5},m=l.modelPos.get((wp?.key||'')+'\0'+r.model)||w,j=((liveHash(r.actor)%17)-8);return[Object.assign(curve({x:tp.x+6,y:tp.y+j},gp,.45,j*.25),{w:1}),Object.assign(curve(gp,qp,.5,j*.1),{w:.55}),Object.assign(curve(qp,w,.5,(w.y-qp.y)*-.08+j),{w:1.35}),Object.assign(curve(w,m,.5,j*.1),{w:.55})]}
function drawClusterMap(tms){const canvas=$('#cluster-map-canvas'),stage=$('#cluster-map-stage');if(!canvas||!stage)return;const rect=stage.getBoundingClientRect();if(rect.width<20||rect.height<20)return;const dpr=Math.min(2,window.devicePixelRatio||1),cw=Math.round(rect.width*dpr),ch=Math.round(rect.height*dpr);if(canvas.width!==cw||canvas.height!==ch){canvas.width=cw;canvas.height=ch}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);const W=rect.width,H=rect.height;ctx.clearRect(0,0,W,H);const all=clusterFilteredRequests(true).slice(0,320),active=all.filter(liveActive),l=clusterLayout(active,W,H),time=tms/1000;ctx.lineCap='round';ctx.lineJoin='round';for(const g of l.gateways){const gp=l.gatewayPos.get(g.node_name),qp=l.queuePos.get(g.node_name);ctx.strokeStyle='rgba(26,128,95,.22)';ctx.lineWidth=1.3;drawCurve(ctx,curve(gp,qp,.5,0));for(const [k,p] of l.workerPos){if((p.w.gateways||[]).includes(g.node_name)){ctx.strokeStyle='rgba(20,127,165,.18)';ctx.lineWidth=1;drawCurve(ctx,curve(qp,p,.5,(p.y-qp.y)*-.08))}}}for(const [key,p] of l.modelPos){const parts=key.split('\0'),wp=l.workerPos.get(parts[0]+'\0'+parts[1]);if(wp){ctx.strokeStyle='rgba(20,127,165,.12)';ctx.lineWidth=.8;drawCurve(ctx,curve(wp,p,.5,0))}}for(const r of active){const tp=l.tenantPos.get(r.tenant),gp=l.gatewayPos.get(r.gateway_name);if(tp&&gp){ctx.strokeStyle=liveColor(r.tenant,.07);ctx.lineWidth=.7;drawCurve(ctx,curve(tp,gp,.45,0))}}drawClusterNodes(ctx,l,active,W,H);S.clusterHit=[];for(const r of all)drawClusterRequest(ctx,l,r,H,time)}
function drawClusterNodes(ctx,l,active,W,H){ctx.save();ctx.textBaseline='middle';for(const [n,p] of l.tenantPos){ctx.fillStyle=liveColor(n,.8);ctx.beginPath();ctx.arc(p.x,p.y,3.8,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(55,74,92,.82)';ctx.textAlign='left';ctx.font='9px ui-monospace,SFMono-Regular,Consolas,monospace';ctx.fillText(n.slice(0,15),p.x+8,p.y)}for(const g of l.gateways){const p=l.gatewayPos.get(g.node_name),q=l.queuePos.get(g.node_name),live=active.filter(r=>r.gateway_name===g.node_name).length;ctx.fillStyle='rgba(255,255,255,.97)';ctx.strokeStyle='rgba(26,128,95,.58)';ctx.lineWidth=1.4;ctx.beginPath();ctx.arc(p.x,p.y,14+Math.min(6,Math.sqrt(live)*2),0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='rgba(37,51,69,.94)';ctx.textAlign='center';ctx.font='700 9px ui-monospace,SFMono-Regular,Consolas,monospace';ctx.fillText(g.node_name.slice(0,16),p.x,p.y-2);ctx.fillStyle='rgba(102,119,138,.90)';ctx.font='8px ui-monospace,SFMono-Regular,Consolas,monospace';ctx.fillText(`${live} live`,p.x,p.y+10);const qr=8+Math.min(10,Math.sqrt(Number(g.queued||0))*2.5);ctx.fillStyle='rgba(247,249,251,.98)';ctx.strokeStyle=g.queued?'rgba(165,102,0,.65)':'rgba(102,119,138,.30)';ctx.beginPath();ctx.arc(q.x,q.y,qr,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='rgba(45,63,81,.88)';ctx.font='700 8px ui-monospace,SFMono-Regular,Consolas,monospace';ctx.fillText(String(g.queued||0),q.x,q.y)}for(const [k,p] of l.workerPos){const w=p.w,util=Math.min(1,Number(w.active||0)/Math.max(1,Number(w.max_concurrent||1))),vr=pct(w.vram_used_bytes||w.vram_bytes,w.vram_total_bytes||w.vram_capacity_bytes),gpu=Math.min(100,Number(w.gpu_utilization_percent||0));ctx.fillStyle='rgba(255,255,255,.97)';ctx.strokeStyle=w.healthy?'rgba(20,127,165,.58)':'rgba(184,61,75,.66)';ctx.lineWidth=1.3;ctx.beginPath();ctx.arc(p.x,p.y,13,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.strokeStyle='rgba(26,128,95,.76)';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,17,-Math.PI/2,-Math.PI/2+Math.PI*2*util);ctx.stroke();if(w.vram_total_bytes||w.vram_capacity_bytes){ctx.strokeStyle='rgba(107,91,181,.76)';ctx.beginPath();ctx.arc(p.x,p.y,20,-Math.PI/2,-Math.PI/2+Math.PI*2*(vr/100));ctx.stroke()}if(gpu){ctx.strokeStyle='rgba(165,102,0,.78)';ctx.beginPath();ctx.arc(p.x,p.y,23,-Math.PI/2,-Math.PI/2+Math.PI*2*(gpu/100));ctx.stroke()}ctx.fillStyle='rgba(37,51,69,.92)';ctx.textAlign='center';ctx.font='600 9px ui-monospace,SFMono-Regular,Consolas,monospace';ctx.fillText(w.name.slice(0,16),p.x,p.y+29);ctx.fillStyle='rgba(102,119,138,.88)';ctx.font='8px ui-monospace,SFMono-Regular,Consolas,monospace';ctx.fillText(`${w.active}/${w.max_concurrent} slots`,p.x,p.y+40)}for(const [k,p] of l.modelPos){ctx.fillStyle='rgba(107,91,181,.62)';ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(92,108,126,.86)';ctx.textAlign='right';ctx.font='8px ui-monospace,SFMono-Regular,monospace';ctx.fillText((p.m.name||p.m.model||'').slice(0,18),p.x-7,p.y-7)}ctx.restore()}
function drawClusterRequest(ctx,l,r,H,time){const route=clusterRoute(l,r,H),seed=(liveHash(r.id)%1000)/1000;ctx.save();ctx.strokeStyle=liveColor(r.tenant,.15);ctx.lineWidth=.6+Math.min(2,Math.sqrt(Math.max(.05,Number(r.estimated_credits||.1)))*.35);for(const x of route)drawCurve(ctx,x);let pts=[];if(r.state==='queued'){const age=liveAge(r),p=Math.min(.46,.03+age*.22);pts=[{p:p>=.45?.43+.015*Math.sin(time*2.2+seed*6.28):p,a:1}]}else if(r.state==='routing'){pts=[{p:.46+Math.min(.4,liveAge(r,'updated_at')*.7),a:1}]}else if(r.state==='running'){for(let k=0;k<2;k++)pts.push({p:.48+.5*((time*.2+seed+k*.47)%1),a:.9-k*.2})}else if(r.state==='streaming'){for(let k=0;k<3;k++)pts.push({p:1-((time*.28+seed+k*.3)%1),a:1-k*.2})}else{const age=liveAge(r,'finished_at'),fade=Math.max(0,1-age/10);pts=[{p:r.state==='failed'?.7:Math.max(.02,1-age*.15),a:fade}]}for(const x of pts){const p=routePoint(route,x.p),col=r.state==='failed'?`rgba(184,61,75,${x.a})`:r.state==='queued'?`rgba(165,102,0,${x.a})`:r.state==='streaming'?`rgba(26,128,95,${x.a})`:liveColor(r.tenant,x.a,44),rad=2.2+Math.min(3.5,Math.sqrt(Math.max(.1,Number(r.estimated_credits||.1))));ctx.shadowColor=col;ctx.shadowBlur=14;ctx.fillStyle=col;ctx.beginPath();ctx.arc(p.x,p.y,rad,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;S.clusterHit.push({x:p.x,y:p.y,r,rad:rad+6})}ctx.restore()}
function clusterPointerMove(e){const canvas=$('#cluster-map-canvas'),tt=$('#cluster-map-tooltip');if(!canvas||!tt)return;const b=canvas.getBoundingClientRect(),x=e.clientX-b.left,y=e.clientY-b.top;let best=null,d=Infinity;for(const h of S.clusterHit){const x2=Math.hypot(h.x-x,h.y-y);if(x2<h.rad&&x2<d){best=h;d=x2}}if(!best){tt.classList.add('hidden');return}const r=best.r,sw=canvas.clientWidth,sh=canvas.clientHeight;tt.innerHTML=`<strong>${esc(r.model||r.path||'Request')}</strong><div>${esc(r.tenant)} · ${esc(r.actor||'–')}</div><div>${esc(r.gateway_name||'Gateway')} → ${esc(r.worker||'–')}</div><div>${esc(r.state)} · ${ms(r.queue_ms||0)} Queue</div><div class="mono">${esc(r.id)}</div>`;tt.classList.remove('hidden');tt.style.left=Math.min(sw-310,Math.max(8,x+14))+'px';tt.style.top=Math.min(sh-120,Math.max(8,y+14))+'px'}

// ---- Live request pulse map -------------------------------------------------
const LIVE_TERMINAL=new Set(['completed','failed','cancelled']);
const liveActive=r=>!LIVE_TERMINAL.has(r.state);
const liveAge=(r,field='queued_at')=>Math.max(0,(Date.now()-new Date(r[field]||r.updated_at||Date.now()).getTime())/1000);
const liveHash=v=>{let h=2166136261;for(const c of String(v||'')){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0};
const liveColor=(v,a=1,l=44)=>`hsla(${(liveHash(v)%290)+30},68%,${Math.min(l,52)}%,${a})`;

function stopLiveStream(){if(S.liveAbort){S.liveAbort.abort();S.liveAbort=null}S.live.connected=false;updateLiveConnection()}
function startLiveStream(){if(!isAdmin()||S.liveAbort)return;const ctl=new AbortController();S.liveAbort=ctl;void liveStreamLoop(ctl.signal)}
async function liveStreamLoop(signal){let retry=650;while(!signal.aborted){try{await liveStreamOnce(signal);retry=650}catch(e){if(signal.aborted)return;S.live.connected=false;updateLiveConnection(e.message);if(e.status===401){showLogin('Sitzung abgelaufen oder Credential ungültig.');return}try{const snap=await api('/gateway/ui-api/live');handleLiveSnapshot(snap)}catch{}await liveSleep(retry,signal);retry=Math.min(5000,retry*1.7)}}}
async function liveStreamOnce(signal){const headers=authHeaders();headers.Accept='text/event-stream';const r=await fetch('/gateway/ui-api/live/stream',{headers,credentials:'same-origin',signal});if(!r.ok){const e=new Error(`Live-Stream HTTP ${r.status}`);e.status=r.status;throw e}if(!r.body)throw new Error('Live-Stream nicht verfügbar');S.live.connected=true;updateLiveConnection();const reader=r.body.getReader(),decoder=new TextDecoder();let buf='';while(!signal.aborted){const {value,done}=await reader.read();if(done)throw new Error('Live-Stream beendet');buf+=decoder.decode(value,{stream:true}).replace(/\r\n/g,'\n');let i;while((i=buf.indexOf('\n\n'))>=0){const raw=buf.slice(0,i);buf=buf.slice(i+2);let event='message';const data=[];for(const line of raw.split('\n')){if(line.startsWith('event:'))event=line.slice(6).trim();else if(line.startsWith('data:'))data.push(line.slice(5).trimStart())}if(event==='snapshot'&&data.length){try{handleLiveSnapshot(JSON.parse(data.join('\n')))}catch{}}}}}
function liveSleep(ms,signal){return new Promise(resolve=>{const t=setTimeout(resolve,ms);signal?.addEventListener('abort',()=>{clearTimeout(t);resolve()},{once:true})})}
function handleLiveSnapshot(snap){S.live.requests=Array.isArray(snap?.requests)?snap.requests:[];S.live.version=Number(snap?.version||0);S.live.generatedAt=snap?.generated_at||null;S.live.counts=snap?.counts||null;S.live.truncated=!!snap?.truncated;S.live.connected=true;updateLiveConnection();renderLivePanel()}
function updateLiveConnection(msg=''){const el=$('#live-stream-state');if(!el)return;el.className='status-chip '+(S.live.connected?'ok':'warn');el.textContent=S.live.connected?'SSE live':(msg?'Reconnect':'verbinde …')}
function liveFiltered(includeTerminal=true){const state=$('#live-state-filter')?.value||'',q=($('#live-search')?.value||'').trim().toLowerCase();return S.live.requests.filter(r=>(includeTerminal||liveActive(r))&&(!state||r.state===state)&&(!q||`${r.tenant} ${r.actor} ${r.application||''} ${r.model||''} ${r.worker||''} ${r.path||''}`.toLowerCase().includes(q)))}
function renderLivePanel(){if(!isAdmin())return;const all=S.live.requests,active=all.filter(liveActive),queued=active.filter(r=>r.state==='queued'),streaming=active.filter(r=>r.state==='streaming'),c=S.live.counts||{};const tokens=active.reduce((n,r)=>n+Number(r.prompt_tokens||r.estimated_prompt_tokens||0)+Number(r.completion_tokens||0),0);if($('#live-active')){$('#live-active').textContent=num(c.active??active.length);$('#live-queued').textContent=num(c.queued??queued.length);$('#live-streaming').textContent=num(c.streaming??streaming.length);$('#live-tokens').textContent=num(tokens);$('#live-flow-empty').classList.toggle('hidden',liveFiltered(false).length>0)}renderLiveRequestList();renderLiveWorkerList();updateLiveConnection()}
function renderLiveRequestList(){const el=$('#live-request-list');if(!el)return;const a=liveFiltered(true).sort((x,y)=>Number(liveActive(y))-Number(liveActive(x))||new Date(y.updated_at)-new Date(x.updated_at)).slice(0,40);el.innerHTML=a.length?a.map(r=>{const dur=r.started_at?liveAge(r,'started_at'):liveAge(r,'queued_at'),tok=Number(r.prompt_tokens||r.estimated_prompt_tokens||0)+Number(r.completion_tokens||0);return `<div class="live-request"><span class="live-request-pulse ${esc(r.state)}"></span><div class="live-request-main"><strong>${esc(r.model||r.path||'request')}</strong><small>${esc(r.tenant)} · ${esc(r.actor||'–')} ${r.worker?`→ ${esc(r.worker)}`:''}</small></div><div class="live-request-meta"><strong>${esc(r.state)}</strong><small>${dur.toFixed(dur<10?1:0)} s · ${num(tok)} tok</small>${liveActive(r)?`<button class="button small danger" data-job-cancel="${esc(r.id)}">Abbrechen</button>`:''}</div></div>`}).join(''):'<div class="empty">Keine Requests für diesen Filter</div>'}
function renderLiveWorkerList(){const el=$('#live-worker-list');if(!el)return;const active=liveFiltered(false),configured=S.overview?.workers||[],names=[...new Set([...configured.map(w=>w.name),...active.map(r=>r.worker).filter(Boolean)])];const max=Math.max(1,...names.map(n=>active.filter(r=>r.worker===n).length));el.innerHTML=names.length?names.map(n=>{const rs=active.filter(r=>r.worker===n),w=configured.find(x=>x.name===n),models=[...new Set(rs.map(r=>r.model).filter(Boolean))].slice(0,6);return `<div class="live-worker"><div class="live-worker-top"><div><strong>${esc(n)}</strong><small>${w?`${w.active}/${w.max_concurrent} Slots`:''}</small></div><span class="status-chip ${w?.healthy?'ok':w?'bad':''}">${rs.length} live</span></div><div class="live-worker-bar"><div style="width:${100*rs.length/max}%"></div></div><div class="live-worker-models">${models.map(m=>`<span>${esc(m)}</span>`).join('')||'<span>idle</span>'}</div></div>`}).join(''):'<div class="empty">Keine Worker</div>'}

function startLiveAnimation(){if(S.liveRAF)return;const loop=t=>{S.liveRAF=requestAnimationFrame(loop);if(S.page==='live')drawLiveFlow(S.livePaused?(S.livePauseTime||t):t);else if(S.page==='infrastructure')drawClusterMap(S.livePaused?(S.livePauseTime||t):t)};S.liveRAF=requestAnimationFrame(loop);for(const b of [$('#live-motion'),$('#cluster-motion')].filter(Boolean))b.textContent=S.livePaused?'Animation fortsetzen':'Animation pausieren'}
function toggleLiveMotion(){S.livePaused=!S.livePaused;if(S.livePaused)S.livePauseTime=performance.now();else S.livePauseTime=0;for(const b of [$('#live-motion'),$('#cluster-motion')].filter(Boolean))b.textContent=S.livePaused?'Animation fortsetzen':'Animation pausieren'}
function cubic(a,b,c,d,t){const u=1-t;return{x:u*u*u*a.x+3*u*u*t*b.x+3*u*t*t*c.x+t*t*t*d.x,y:u*u*u*a.y+3*u*u*t*b.y+3*u*t*t*c.y+t*t*t*d.y}}
function curve(a,d,bias=.5,bend=0){const dx=d.x-a.x;return{a,b:{x:a.x+dx*bias,y:a.y+bend},c:{x:d.x-dx*bias,y:d.y-bend},d}}
function routePoint(route,p){p=Math.max(0,Math.min(.999999,p));const weights=route.map(s=>s.w||1),sum=weights.reduce((a,b)=>a+b,0);let x=p*sum;for(let i=0;i<route.length;i++){if(x<=weights[i]||i===route.length-1)return cubic(route[i].a,route[i].b,route[i].c,route[i].d,x/weights[i]);x-=weights[i]}return route.at(-1).d}
function drawCurve(ctx,s){ctx.beginPath();ctx.moveTo(s.a.x,s.a.y);ctx.bezierCurveTo(s.b.x,s.b.y,s.c.x,s.c.y,s.d.x,s.d.y);ctx.stroke()}
function liveLayout(reqs,W,H){const marginY=70;const counts=new Map();for(const r of reqs)counts.set(r.tenant,(counts.get(r.tenant)||0)+1);let tenants=[...counts].sort((a,b)=>b[1]-a[1]).map(x=>x[0]);const visibleTenants=tenants.slice(0,8),tenantPos=new Map();visibleTenants.forEach((n,i)=>tenantPos.set(n,{x:Math.max(70,W*.075),y:marginY+(H-2*marginY)*(visibleTenants.length===1?.5:i/Math.max(1,visibleTenants.length-1))}));const admission={x:W*.31,y:H*.50},queue={x:W*.50,y:H*.50};const configured=S.overview?.workers||[],workerNames=[...new Set([...configured.map(w=>w.name),...reqs.map(r=>r.worker).filter(Boolean)])].slice(0,8),workerPos=new Map();workerNames.forEach((n,i)=>workerPos.set(n,{x:W*.78,y:marginY+(H-2*marginY)*(workerNames.length===1?.5:i/Math.max(1,workerNames.length-1))}));const modelPos=new Map();for(const w of workerNames){const models=[...new Set(reqs.filter(r=>r.worker===w).map(r=>r.model).filter(Boolean))].slice(0,4),wp=workerPos.get(w);models.forEach((m,i)=>{const off=(i-(models.length-1)/2)*26;modelPos.set(`${w}\0${m}`,{x:W*.94,y:Math.max(42,Math.min(H-42,wp.y+off))})})}return{tenantPos,visibleTenants,admission,queue,workerPos,workerNames,modelPos}}
function tenantLane(layout,r,H){const p=layout.tenantPos.get(r.tenant);if(p)return p;const lanes=[...layout.tenantPos.values()];if(lanes.length)return lanes[liveHash(r.tenant)%lanes.length];return{x:70,y:H*.5}}
function requestRoute(layout,r,H){const tp=tenantLane(layout,r,H),a=layout.admission,q=layout.queue,w=layout.workerPos.get(r.worker)||{x:q.x+140,y:q.y+(liveHash(r.model)%160)-80},m=layout.modelPos.get(`${r.worker}\0${r.model}`)||w;const jitter=((liveHash(r.actor)%21)-10)*1.1;return[Object.assign(curve({x:tp.x+8,y:tp.y+jitter},a,.45,jitter*.35),{w:1.25}),Object.assign(curve(a,q,.5,jitter*.15),{w:.75}),Object.assign(curve(q,w,.52,(w.y-q.y)*-.08+jitter),{w:1.45}),Object.assign(curve(w,m,.5,jitter*.1),{w:.55})]}
function drawLiveFlow(tms){const canvas=$('#live-flow-canvas'),stage=$('#live-flow-stage');if(!canvas||!stage)return;const rect=stage.getBoundingClientRect();if(rect.width<20||rect.height<20)return;const dpr=Math.min(2,window.devicePixelRatio||1),cw=Math.round(rect.width*dpr),ch=Math.round(rect.height*dpr);if(canvas.width!==cw||canvas.height!==ch){canvas.width=cw;canvas.height=ch}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);const W=rect.width,H=rect.height;ctx.clearRect(0,0,W,H);const all=liveFiltered(true).slice(0,220),layout=liveLayout(all,W,H),active=all.filter(liveActive),time=tms/1000;
  // topology trunks
  ctx.lineCap='round';ctx.lineJoin='round';ctx.shadowBlur=0;ctx.strokeStyle='rgba(92,117,140,.22)';ctx.lineWidth=1;
  for(const [name,p] of layout.tenantPos){drawCurve(ctx,curve({x:p.x+7,y:p.y},layout.admission,.46,0))}
  ctx.strokeStyle='rgba(26,128,95,.22)';ctx.lineWidth=1.3;drawCurve(ctx,curve(layout.admission,layout.queue,.5,0));
  for(const [name,p] of layout.workerPos){ctx.strokeStyle='rgba(20,127,165,.20)';ctx.lineWidth=1;drawCurve(ctx,curve(layout.queue,p,.52,(p.y-layout.queue.y)*-.08))}
  for(const [key,p] of layout.modelPos){const worker=key.split('\0')[0],wp=layout.workerPos.get(worker);if(wp){ctx.strokeStyle='rgba(20,127,165,.14)';ctx.lineWidth=.8;drawCurve(ctx,curve(wp,p,.5,0))}}
  drawLiveNodes(ctx,layout,W,H,active);
  S.liveHit=[];
  for(const r of all){drawLiveRequest(ctx,layout,r,W,H,time)}
}
function drawLiveNodes(ctx,l,W,H,active){ctx.save();ctx.textBaseline='middle';ctx.font='600 10px ui-monospace,SFMono-Regular,Consolas,monospace';for(const [n,p] of l.tenantPos){const c=active.filter(r=>r.tenant===n).length;ctx.fillStyle=liveColor(n,.85);ctx.beginPath();ctx.arc(p.x,p.y,4.2,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='rgba(48,67,85,.90)';ctx.textAlign='left';ctx.fillText(n.slice(0,18),p.x+10,p.y-5);ctx.fillStyle='rgba(102,119,138,.88)';ctx.font='9px ui-monospace,SFMono-Regular,Consolas,monospace';ctx.fillText(`${c} live`,p.x+10,p.y+8);ctx.font='600 10px ui-monospace,SFMono-Regular,Consolas,monospace'}drawHub(ctx,l.admission,'ADMISSION',active.length);drawHub(ctx,l.queue,'FAIR QUEUE',active.filter(r=>r.state==='queued').length);for(const [n,p] of l.workerPos){const c=active.filter(r=>r.worker===n).length;ctx.strokeStyle=c?'rgba(26,128,95,.58)':'rgba(20,127,165,.30)';ctx.fillStyle='rgba(255,255,255,.96)';ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(p.x,p.y,10,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='rgba(42,59,77,.92)';ctx.textAlign='center';ctx.font='600 9px ui-monospace,SFMono-Regular,Consolas,monospace';ctx.fillText(n.slice(0,16),p.x,p.y+19);ctx.fillStyle='rgba(102,119,138,.90)';ctx.fillText(`${c} live`,p.x,p.y+31)}for(const [key,p] of l.modelPos){const m=key.split('\0')[1];ctx.fillStyle='rgba(20,127,165,.55)';ctx.beginPath();ctx.arc(p.x,p.y,2.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(88,105,123,.82)';ctx.textAlign='right';ctx.font='8px ui-monospace,SFMono-Regular,monospace';ctx.fillText((m||'').slice(0,18),p.x-7,p.y-7)}ctx.restore()}
function drawHub(ctx,p,label,count){ctx.save();const radius=13+Math.min(7,Math.sqrt(count||0)*2);ctx.strokeStyle='rgba(26,128,95,.42)';ctx.fillStyle='rgba(255,255,255,.97)';ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(p.x,p.y,radius,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='rgba(37,51,69,.94)';ctx.textAlign='center';ctx.font='700 9px ui-monospace,SFMono-Regular,Consolas,monospace';ctx.fillText(label,p.x,p.y-2);ctx.fillStyle='rgba(102,119,138,.90)';ctx.font='9px ui-monospace,SFMono-Regular,Consolas,monospace';ctx.fillText(`${count||0}`,p.x,p.y+10);ctx.restore()}
function drawLiveRequest(ctx,layout,r,W,H,time){const route=requestRoute(layout,r,H),base=liveColor(r.tenant,.20),width=.55+Math.min(2.6,Math.sqrt(Math.max(.05,Number(r.estimated_credits||.1)))*.4);ctx.save();ctx.strokeStyle=base;ctx.lineWidth=width;for(const s of route)drawCurve(ctx,s);const seed=(liveHash(r.id)%1000)/1000;let pts=[];if(r.state==='queued'){const age=liveAge(r),p=Math.min(.48,.05+age*.22);pts=[{p:p>=.47?.455+.018*Math.sin(time*2.2+seed*6.28):p,a:.95}]}else if(r.state==='routing'){const age=liveAge(r,'updated_at');pts=[{p:.48+Math.min(.43,age*.75),a:1}]}else if(r.state==='running'){for(let k=0;k<2;k++)pts.push({p:.48+(.50*((time*.22+seed+k*.48)%1)),a:.85-k*.18})}else if(r.state==='streaming'){for(let k=0;k<3;k++)pts.push({p:1-((time*.30+seed+k*.29)%1),a:1-k*.20});pts.push({p:.98,a:.75})}else{const age=liveAge(r,'finished_at'),fade=Math.max(0,1-age/10),p=r.state==='failed'?.72:Math.max(.02,1-age*.16);pts=[{p,a:fade}]}
  for(const x of pts){const p=routePoint(route,x.p),terminal=LIVE_TERMINAL.has(r.state),col=r.state==='failed'?`rgba(184,61,75,${x.a})`:r.state==='queued'?`rgba(165,102,0,${x.a})`:r.state==='streaming'?`rgba(26,128,95,${x.a})`:liveColor(r.tenant,x.a,44);const rad=2.2+Math.min(4,Math.sqrt(Math.max(.1,Number(r.estimated_credits||.1))));ctx.shadowColor=col;ctx.shadowBlur=terminal?8:16;ctx.fillStyle=col;ctx.beginPath();ctx.arc(p.x,p.y,rad,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;S.liveHit.push({x:p.x,y:p.y,r,rad:rad+6})}
  ctx.restore()}
function showLiveTooltip(r,x,y){const tt=$('#live-flow-tooltip'),stage=$('#live-flow-stage');if(!tt||!stage)return;const tok=Number(r.prompt_tokens||r.estimated_prompt_tokens||0)+Number(r.completion_tokens||0);tt.innerHTML=`<strong>${esc(r.model||r.path||'Request')}</strong><div>${esc(r.tenant)} · ${esc(r.actor||'–')}</div><div class="mono">${esc(r.id)}</div><div>${esc(r.state)} ${r.worker?`→ ${esc(r.worker)}`:''}</div><div>${num(tok)} Tokens · ${credits(r.estimated_credits)} cr est.</div>`;tt.classList.remove('hidden');const sw=stage.clientWidth,sh=stage.clientHeight;tt.style.left=Math.min(sw-310,Math.max(8,x+14))+'px';tt.style.top=Math.min(sh-120,Math.max(8,y+14))+'px'}
function livePointerMove(e){const canvas=$('#live-flow-canvas'),tt=$('#live-flow-tooltip');if(!canvas||!tt)return;const b=canvas.getBoundingClientRect(),x=e.clientX-b.left,y=e.clientY-b.top;let best=null,dist=Infinity;for(const h of S.liveHit){const d=Math.hypot(h.x-x,h.y-y);if(d<h.rad&&d<dist){best=h;dist=d}}if(best)showLiveTooltip(best.r,x,y);else tt.classList.add('hidden')}

$('#cluster-search')?.addEventListener('input',renderClusterPanel);
$('#cluster-motion')?.addEventListener('click',toggleLiveMotion);
$('#cluster-map-canvas')?.addEventListener('pointermove',clusterPointerMove);
$('#cluster-map-canvas')?.addEventListener('pointerleave',()=>$('#cluster-map-tooltip')?.classList.add('hidden'));

$('#live-state-filter')?.addEventListener('change',renderLivePanel);
$('#live-search')?.addEventListener('input',renderLivePanel);
$('#live-motion')?.addEventListener('click',toggleLiveMotion);
$('#live-flow-canvas')?.addEventListener('pointermove',livePointerMove);
$('#live-flow-canvas')?.addEventListener('pointerleave',()=>$('#live-flow-tooltip')?.classList.add('hidden'));
document.addEventListener('click',e=>{const b=e.target.closest('[data-close-dialog]');if(!b)return;document.getElementById(b.dataset.closeDialog)?.close()});

$('#worker-cards')?.addEventListener('click',async e=>{const b=e.target.closest('[data-worker-mode]');if(b){try{await api('/gateway/ui-api/workers/'+encodeURIComponent(b.dataset.worker)+'/maintenance',{method:'POST',body:JSON.stringify({mode:b.dataset.workerMode})});toast(`Worker ${b.dataset.worker}: ${b.dataset.workerMode}`);await refreshAll(false)}catch(err){toast(err.message,true)}return}const c=e.target.closest('[data-circuit-reset]');if(c){try{await api('/gateway/ui-api/workers/'+encodeURIComponent(c.dataset.circuitReset)+'/circuit/reset',{method:'POST'});toast('Circuit Breaker zurückgesetzt');await refreshAll(false)}catch(err){toast(err.message,true)}}});

init();
